if TYPE_CHECKING:
    from collections.abc import AsyncIterator


class Answer(BaseModel):
    code: str


Call = tuple[list[ModelMessage], AgentInfo]
MESSAGE = (
    "(Asked with the inline AI in a Python cell, not in the chat box.)\n\nEditor code: q1\n\nInstruction: sort by wins"
)


def answering(codes: list[str], calls: list[Call]) -> FunctionModel:
    """A stand-in model that answers with each of `codes` in turn (the last one again after
    that) and records what each request sent.
    """

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        calls.append((list(messages), info))
        code = codes[min(len(calls), len(codes)) - 1]
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, {"code": code})])

    return FunctionModel(respond)


def an_edit(**given: Any) -> Inline:
    asked = {
        "label": "edit",
        "output_type": Answer,
        "rules": "RULES OF THIS PLACE",
        "instruction": "sort by wins",
        "where": "a Python cell",
        "answer": lambda output: output.code,
        "context": "REFERENCE: q1 is a polars DataFrame",
    } | given
    return Inline(**asked)


def ask(made: Session, codes: list[str], calls: list[Call] | None = None, **given: Any) -> Any:
    with ds.ai.agent.override(model=answering(codes, [] if calls is None else calls)):
        return asyncio.run(made.ask(MESSAGE, inline=an_edit(**given)))


def texts(messages: list[ModelMessage]) -> str:
    """Everything the messages hold as text: prompts, answers, tool arguments and returns."""
    parts = [part for message in messages for part in message.parts]
    return "\n".join(str(getattr(part, "content", "") or getattr(part, "args", "")) for part in parts)


async def nothing(_: str) -> None:
    return None


def test_it_is_the_chat_agent_with_the_places_rules_and_no_tools() -> None:
    calls: list[Call] = []
    result = ask(Session(), ["q1.sort('wins')"], calls)
    assert result.output == Answer(code="q1.sort('wins')")
    (_, info) = calls[0]
    assert info.function_tools == []  # not even the one that loads a capability
    assert "RULES OF THIS PLACE" in info.instructions
    assert "REFERENCE: q1 is a polars DataFrame" in info.instructions
    assert "1v1" in info.instructions  # the chat agent's own instructions: it is that agent


def test_the_turns_real_messages_join_the_chats_history() -> None:
    made = Session()
    ask(made, ["q1.sort('wins')"])
    kept = texts(made.ai_history)
    assert MESSAGE in kept  # the message as sent, where it was asked included
    assert "q1.sort('wins')" in kept  # the answer as the model gave it
    # the place's rules and reference were instructions for that turn: not in the messages
    assert "REFERENCE" not in kept
    assert "RULES OF THIS PLACE" not in kept


def test_the_chat_and_the_next_inline_turn_read_it_without_its_reference() -> None:
    made = Session()
    ask(made, ["q1.sort('wins')"])
    calls: list[Call] = []
    ask(made, ["x"], calls, context="")
    assert "q1.sort('wins')" in texts(calls[0][0])

    seen: list[tuple[str, str]] = []

    async def chat(messages: list[ModelMessage], info: AgentInfo) -> AsyncIterator[str]:
        seen.append((texts(messages), info.instructions or ""))
        yield "You asked to sort by wins."

    with ds.ai.agent.override(model=FunctionModel(stream_function=chat)):
        result = asyncio.run(made.ask("why did you sort it that way?", nothing))
    assert not result.error
    sent, instructions = seen[0]
    assert "sort by wins" in sent
    assert "q1.sort('wins')" in sent
    # a chat turn again: the inline turn's rules and reference are gone
    assert "RULES OF THIS PLACE" not in instructions
    assert "REFERENCE" not in instructions


def test_an_inline_turn_that_ends_during_a_chat_turn_is_kept() -> None:
    made = Session()

    async def chat(_messages: list[ModelMessage], _info: AgentInfo) -> AsyncIterator[str]:
        # an inline turn asked and answered while the chat turn runs
        with ds.ai.agent.override(model=answering(["during()"], [])):
            await made.ask(MESSAGE, inline=an_edit())
        yield "an answer"

    with ds.ai.agent.override(model=FunctionModel(stream_function=chat)):
        asyncio.run(made.ask("a question", nothing))
    kept = texts(made.ai_history)
    assert "a question" in kept
    assert "an answer" in kept
    assert "during()" in kept


def test_a_failing_answer_goes_back_to_the_model_then_is_returned_anyway() -> None:
    calls: list[Call] = []
    result = ask(
        Session(), ["bad"], calls, check=lambda output: "That fails. Send it again." if output.code == "bad" else ""
    )
    assert len(calls) == inline.MAX_FIXES + 1
    assert (result.output, result.fixes) == (Answer(code="bad"), inline.MAX_FIXES)
    assert texts(calls[-1][0]).count("That fails.") == inline.MAX_FIXES


def test_a_failed_turn_adds_nothing() -> None:
    made = Session()

    def broken(_messages: list[ModelMessage], _info: AgentInfo) -> ModelResponse:
        raise RuntimeError("the model is down")

    with ds.ai.agent.override(model=FunctionModel(broken)):
        result = asyncio.run(made.ask(MESSAGE, inline=an_edit()))
    assert result.error == "RuntimeError: the model is down"
    assert result.output is None
    assert made.ai_history == []
    assert made.inline_rows == []


def test_it_is_logged_under_its_label_with_the_answer_for_the_file_only() -> None:
    seen: list[dict[str, Any]] = []
    enable_call_logs()  # another test may have turned ds's records off
    sink = logger.add(lambda message: seen.append(dict(message.record["extra"])), filter=lambda r: "kind" in r["extra"])
    try:
        ask(Session(), ["q1.sort('wins')"], name="inline edit (python)")
    finally:
        logger.remove(sink)
    record = next(extra for extra in seen if extra.get("source") == "inline-edit")
    assert (record["kind"], record["name"], record["prompt"]) == ("agent", "inline edit (python)", "sort by wins")
    assert record["full"] == {"reply": "q1.sort('wins')"}
    assert [inline.agent_name(label) for label in inline.LABELS] == [
        "inline-edit",
        "inline-fill",
        "inline-terminal",
        "inline-assign",
    ]


def test_the_chat_pane_gets_a_quiet_row_for_it() -> None:
    state = State(_reflex_internal_init=True)  # a flag, not a password
    made = state._session()
    ask(made, ["q1.sort('wins')"], name="inline edit (python)")
    ask(made, ["x = 1"], row=False)  # a place that draws its own row ("/assign")
    State.refresh_usage.fn(state)  # what the browser triggers after an inline call
    (row,) = [item for item in state.chat if item.kind == "inline"]
    assert (row.name, row.text, row.detail) == (
        "inline edit (python)",
        "a Python cell · sort by wins",
        "q1.sort('wins')",
    )
    assert not row.open  # folded until its caret is clicked
    State.toggle_mention.fn(state, row.key)
    assert state.chat[-1].open
    assert made.inline_rows == []  # shown once


def test_an_inline_edit_is_a_turn_of_the_sessions_chat(monkeypatch: pytest.MonkeyPatch) -> None:
    made = Session()
    monkeypatch.setattr(inline_edit, "find_session", lambda _token: made)
    body = {"language": "python", "before": "q1", "instruction": "sort by wins", "token": "t"}
    calls: list[Call] = []
    with ds.ai.agent.override(model=answering(["q1.sort('wins')"], calls)):
        answer = asyncio.run(inline_edit.edit(body))
    assert answer["code"] == 'q1.sort("wins")'  # as ruff formats it
    kept = texts(made.ai_history)
    assert "(Asked with the inline AI in a Python cell, not in the chat box.)" in kept
    assert "Instruction: sort by wins" in kept
    # the variables and tables are the turn's reference: sent, not kept
    assert "SmashDb tables" in calls[0][1].instructions
    assert "SmashDb tables" not in kept


# -- one memory across the chat box and every inline place ------------------------------------
# Each place asked through its real entry point, as the app calls it, with an answer of the
# form that place needs.
PLACES: dict[str, tuple[Any, dict[str, Any]]] = {
    "edit": (
        lambda _made, text: inline_edit.edit({"language": "python", "before": "q1", "instruction": text, "token": "t"}),
        {"code": "q1"},
    ),
    "terminal": (lambda _made, text: inline_terminal.ask({"instruction": text, "token": "t"}), {"command": "ls"}),
    "fill": (
        lambda made, text: inline_fill.fill(made, form_by_key("get_player_usage"), {}, text),
        {"player": "Sparg0", "vs_characters": ["steve"], "setting": "offline", "sets": 90},
    ),
    "assign": (
        lambda made, text: assign.propose(made, "t", f"who = {text}"),
        {"name": "who", "code": "who = 'bob'", "basis": "knowledge"},
    ),
}


def ask_in(place: str, made: Session, text: str) -> str:
    """Ask `text` in an inline place; the text of everything that request sent the model."""
    run, output = PLACES[place]
    sent: list[str] = []

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        sent.append(texts(messages))
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, output)])

    with ds.ai.agent.override(model=FunctionModel(respond)):
        asyncio.run(run(made, text))
    assert sent, f"{place} never reached the model"
    return sent[0]


def ask_in_chat(made: Session, text: str) -> str:
    """Ask `text` in the chat box; the text of everything that request sent the model."""
    sent: list[str] = []

    async def chat(messages: list[ModelMessage], _info: AgentInfo) -> AsyncIterator[str]:
        sent.append(texts(messages))
        yield "ok"

    with ds.ai.agent.override(model=FunctionModel(stream_function=chat)):
        assert not asyncio.run(made.ask(text, nothing)).error
    return sent[0]


@pytest.fixture
def made(monkeypatch: pytest.MonkeyPatch) -> Session:
    """The session of the tab every place is asked from."""
    made = Session()
    monkeypatch.setattr(inline_edit, "find_session", lambda _token: made)
    monkeypatch.setattr(inline_terminal, "find_session", lambda _token: made)
    return made


@pytest.mark.parametrize("place", PLACES)
def test_what_the_chat_was_told_is_known_in_every_inline_place(made: Session, place: str) -> None:
    ask_in_chat(made, "my name is bob")
    assert "my name is bob" in ask_in(place, made, "am i tod or bob")


@pytest.mark.parametrize("place", PLACES)
def test_a_correction_made_in_an_inline_place_is_known_everywhere_else(made: Session, place: str) -> None:
    ask_in_chat(made, "my name is bob")
    ask_in(place, made, "sorry my name is actually tod")
    correction = "sorry my name is actually tod"
    for other in PLACES:
        if other != place:
            sent = ask_in(other, made, "am i tod or bob")
            # both are there, the correction after what it corrects
            assert sent.index("my name is bob") < sent.index(correction), other
    sent = ask_in_chat(made, "am i tod or bob")
    assert sent.index("my name is bob") < sent.index(correction)


